(() => {
 const {m,pct,slider,select,bars}=CVA_UI;
 CVA_LESSONS.push({id:'cva-total',name:'Putting capital together',stage:'04 · Capital and implementation',title:'Eleven charges, one SA-CVA total',intro:'Add six delta charges and five vega charges. SA-CVA does not add curvature, DRC or RRAO, and does not run FRTB’s three correlation scenarios.',chart:'The contribution of each risk class',inputs:[slider('size','Portfolio sensitivity scale',0,200,5,100,'%'),slider('hedge','Eligible hedge scale',0,200,5,100,'%'),slider('vol','Vega sensitivity scale',0,200,5,100,'%')],challenge:'Double both portfolio and hedge scales. Then double only the hedge scale. Why do the results differ?',formula:'SA-CVA = Σ six delta class charges + Σ five vega class charges\nmCVA = 1',key:'No cross-class or delta-versus-vega diversification is applied. The 0.65 scalar in reduced BA-CVA is not the SA-CVA multiplier.',simpleTitle:'Diversification has defined boundaries',simple:'The framework recognises specified offsets inside each class. Once those class charges are calculated, they add. A gain in one class does not cancel capital in another.',scope:'Uses the six laboratory portfolios with default leading sensitivities 100/60 and hedges 70/20. Controls scale those synthetic sensitivities. All other factors are zero. Full-scope capital before Chapter 7 transition.',pages:[[408,'5.14–5.17 · delta and vega classes'],[410,'5.24 · aggregation multiplier']],compute(s){let rows=[],values=[];for(const p of CVA_CLASSES){let total=0;for(const mode of p.cp?['delta']:['delta','vega']){const f=s.size/100*(mode==='vega'?s.vol/100:1),h=s.hedge/100*(mode==='vega'?s.vol/100:1),k=CVA_CLASS_CALC(p,{mode,a:100*f,b:60*f,ha:70*h,hb:20*h}).k;rows.push([p.name,mode,m(k)]);total+=k;}values.push(total);}const total=CVA.sum(values);return {stats:[['SA-CVA capital',m(total)],['Delta classes','6'],['Vega classes','5']],bars:bars(CVA_CLASSES.map(p=>p.name),values),headers:['Risk class','Sensitivity type','Charge'],rows:[...rows,['Total','No further diversification',m(total)]],explanation:'The eleven component charges sum to '+m(total)+'. A hedge can reduce a component, but excessive or wrongly signed hedging can increase it. Even matching weighted sensitivities leaves the hedge-disallowance contribution.',note:'This is CVA risk capital, not a total combining CCR default capital and market-risk capital.'};}});
 CVA_LESSONS.push({id:'cva-governance',name:'Scope, permission and data',stage:'04 · Capital and implementation',title:'A calculation needs a governed valuation process',intro:'SA-CVA requires PRA permission and a dedicated CVA risk-management function. Reliable exposure, credit curves, eligible hedges and independent validation are part of the framework.',chart:'Illustrative implementation readiness',inputs:[select('permission','PRA SA-CVA permission',[['yes','Granted for the selected scope'],['no','Not granted']],'no'),slider('data','Data and model controls completed',0,5,1,3,'of 5'),slider('controls','Governance controls completed',0,5,1,2,'of 5')],challenge:'Set every control to complete but leave permission absent. Can readiness replace regulatory permission?',formula:'Operational readiness ≠ permission to use SA-CVA',key:'The progress indicators are an educational checklist, not a regulatory scoring system or approval threshold.',simpleTitle:'Good numbers need traceable inputs and accountable owners',simple:'A convincing chart cannot establish that a model is fit for regulatory use. Firms need documented inputs, reconciled transactions, independent challenge and the ability to reproduce the calculation.',scope:'Illustrative self-assessment only. Readiness scores never determine legal eligibility. Actual permissions can cover a defined portion of the portfolio, with other netting sets using BA-CVA under the rules.',pages:[[397,'3.1–3.2 · scope and exemptions'],[403,'5.1–5.4 · permission'],[407,'5.13 · validation and controls'],[408,'5.13 · model oversight']],notes:[['Scope comes before calculation','Covered transactions include derivatives subject to the specified exclusions. Securities financing transactions enter where fair valued and CVA risk is material. Intragroup exclusions have legal, risk-management and notification conditions; they are not automatic.'],['Five data and model checks','Check market-implied counterparty curves and justified proxies; consistent market LGD; full-revaluation exposure paths with risk-neutral drifts; enforceable netting and collateral including MPOR; and valuation calibration and reconciliation.'],['Five governance checks','Check a dedicated CVA function; independent validation; senior-management oversight; secure data with audit trails; and documented monitoring, benchmarking and reporting. Capital is calculated at least monthly, with the ability to calculate daily.'],['Other approaches and transition','BA-CVA and the alternative approach are separate methods. Chapter 7 allows specified transitional treatment until 1 January 2030; it is not an automatic flat discount to every SA-CVA result. The applets show the full-scope calculation.']],compute(s){return {stats:[['Permission',s.permission==='yes'?'Granted':'Required'],['Data / model checks',s.data+' / 5'],['Governance checks',s.controls+' / 5']],bars:bars(['Data and model','Governance'],[s.data,s.controls]),headers:['Area','Status','Interpretation'],rows:[['Permission',s.permission==='yes'?'Granted':'Absent','Required for the approved SA-CVA scope'],['Data and models',s.data+' / 5','Illustrative checklist completion'],['Governance',s.controls+' / 5','Illustrative checklist completion']],explanation:s.permission==='no'?'Even a fully completed checklist does not permit SA-CVA use without PRA permission. Build the evidence and obtain the required permission for the intended scope.':'Permission covers its agreed scope. Ongoing model validation, data quality and reporting obligations continue after approval.',note:'Read the linked PRA provisions for the full requirements and exclusions.'};}});
})();

